type Ownership = "shared" | "locale" | "source";
type FieldSpec = Readonly<Record<string, unknown>> & {
  readonly type: string;
  readonly ownership?: Ownership;
};
type FieldCatalog = Readonly<Record<string, FieldSpec>>;
export function richTextBlockFieldOwnership(
  kind: RichTextBlockKind,
  field: string,
): Ownership | undefined {
  return (richTextBlockCatalog[kind].fields as FieldCatalog)[field]?.ownership;
}
export function pageSectionFieldOwnership(
  kind: PageSectionKind,
  field: string,
): Ownership | undefined {
  return (pageSectionCatalog[kind].fields as FieldCatalog)[field]?.ownership;
}
export function richTextCollaborativeTextFields(
  kind: RichTextBlockKind,
): readonly string[] {
  return richTextCollaborativeTextCatalog[kind];
}
export function pageSectionCollaborativeTextFields(
  kind: PageSectionKind,
): readonly string[] {
  return pageSectionCollaborativeTextCatalog[kind];
}
function collaborativePatternMatches(pattern: string, path: string): boolean {
  const expected = pattern.split(".");
  const actual = path.split(".");
  if (expected.length !== actual.length) return false;
  return expected.every((segment, index) => {
    if (!segment.endsWith("[*]")) return segment === actual[index];
    const name = segment.slice(0, -3);
    const value = actual[index];
    if (!value.startsWith(name + "[") || !value.endsWith("]")) return false;
    return /^\d+$/.test(value.slice(name.length + 1, -1));
  });
}
export function isRichTextCollaborativeTextPath(
  kind: RichTextBlockKind,
  path: string,
): boolean {
  if (
    richTextCollaborativeTextCatalog[kind]
      .filter((field) => field !== "content")
      .some((field) => collaborativePatternMatches(field, path))
  )
    return true;
  const content = richTextBlockCatalog[kind].content;
  if (content === "locale_text") return path === "content";
  const inlineLeaf = String.raw`(?:text\.text|link\.content\[\d+\]\.text|mathInline\.source)`;
  if (content === "inline")
    return new RegExp(String.raw`^content\[\d+\]\.${inlineLeaf}$`).test(path);
  if (content === "table")
    return new RegExp(
      String.raw`^content\.rows\[\d+\]\.cells\[\d+\]\.content\[\d+\]\.${inlineLeaf}$`,
    ).test(path);
  return false;
}
export function isPageSectionCollaborativeTextPath(
  kind: PageSectionKind,
  path: string,
): boolean {
  return pageSectionCollaborativeTextCatalog[kind].some((field) =>
    collaborativePatternMatches(field, path),
  );
}

export interface ContentBlockValidationIssue {
  readonly path: string;
  readonly code: string;
  readonly message: string;
}
export class ContentBlockValidationError extends Error {
  readonly issue: ContentBlockValidationIssue;
  constructor(issue: ContentBlockValidationIssue) {
    super(`${issue.path}: ${issue.message} (${issue.code})`);
    this.name = "ContentBlockValidationError";
    this.issue = issue;
  }
}

