function richStorageJSON(
  data: RichTextBlockData | RichTextBlockLocaleData,
): Record<string, unknown> {
  return mutableRecord(
    data.$typeName.endsWith("LocaleData")
      ? toJson(RichTextBlockLocaleDataSchema, data as RichTextBlockLocaleData)
      : toJson(RichTextBlockDataSchema, data as RichTextBlockData),
  );
}
function pageStorageJSON(
  data: PageSectionData | PageSectionLocaleData,
): Record<string, unknown> {
  return mutableRecord(
    data.$typeName.endsWith("LocaleData")
      ? toJson(PageSectionLocaleDataSchema, data as PageSectionLocaleData)
      : toJson(PageSectionDataSchema, data as PageSectionData),
  );
}
export function materializeRichTextDocumentStorage(
  profile: RichTextProfile,
  sourceLocale: string,
  rows: readonly ContentBlockStorageRow[],
): RichTextDocument {
  profileName(profile);
  if (!sourceLocale.trim())
    fail("$.sourceLocale", "required", "source locale is required");
  const seen = new Set<string>();
  const localeBlocks = new Map<string, Record<string, unknown>[]>();
  localeBlocks.set(sourceLocale, []);
  const nodes = [...rows].sort(compareStorageRows).map((row) => {
    if (
      row.family !== "richText" ||
      !richTextBlockKinds.includes(row.kind as RichTextBlockKind)
    )
      fail("$.kind", "kind", "non-rich row in rich-text document");
    requireUuid(row.blockId, "$.blockId");
    if (seen.has(row.blockId))
      fail("$.blockId", "duplicate_id", "duplicate Block ID");
    seen.add(row.blockId);
    if (row.parentBlockId !== undefined)
      requireUuid(row.parentBlockId, "$.parentBlockId");
    const shared = richStorageJSON(row.sharedData as RichTextBlockData);
    const protoCase = (row.sharedData as RichTextBlockData).value.case;
    if (
      richTextBlockKindByProtoCase[
        protoCase as keyof typeof richTextBlockKindByProtoCase
      ] !== row.kind
    )
      fail(
        "$.kind",
        "kind_mismatch",
        "row payload kind does not match storage kind",
      );
    if (!row.locales.some((locale) => locale.locale === sourceLocale))
      fail(
        "$.sourceLocale",
        "source_overlay",
        "each base Block requires source locale data",
      );
    for (const locale of row.locales) {
      const values = localeBlocks.get(locale.locale) ?? [];
      values.push({
        blockId: row.blockId,
        ...richStorageJSON(locale.data as RichTextBlockLocaleData),
      });
      localeBlocks.set(locale.locale, values);
    }
    return {
      block: { id: row.blockId, ...shared },
      placement: {
        ...(row.parentBlockId === undefined
          ? {}
          : { parentBlockId: row.parentBlockId }),
        index: row.position,
      },
    };
  });
  const raw = {
    blockCatalogFingerprint: contentBlockCatalogFingerprint,
    profile,
    sourceLocale,
    base: { nodes },
    localeOverlays: [...localeBlocks]
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([locale, blocks]) => ({ locale, blocks })),
  } as JsonValue;
  return normalizeRichTextDocument(
    fromJson(RichTextDocumentSchema, raw),
    ContentValidationMode.RESTORE_SNAPSHOT,
  );
}
export function materializeLocalizedRichTextDocumentStorage(
  profile: RichTextProfile,
  locale: string,
  rows: readonly ContentBlockStorageRow[],
): LocalizedRichTextDocument {
  return materializeLocalizedRichTextDocument(
    materializeRichTextDocumentStorage(profile, locale, rows),
    locale,
  );
}
export function materializePageDocumentStorage(
  sourceLocale: string,
  rows: readonly ContentBlockStorageRow[],
): PageDocument {
  if (!sourceLocale.trim())
    fail("$.sourceLocale", "required", "source locale is required");
  const sectionRows = new Map<string, ContentBlockStorageRow>();
  const richRows = new Map<string, ContentBlockStorageRow>();
  for (const row of rows) {
    requireUuid(row.blockId, "$.blockId");
    if (sectionRows.has(row.blockId) || richRows.has(row.blockId))
      fail("$.blockId", "duplicate_id", "duplicate Block ID");
    if (
      row.family === "pageSection" &&
      pageSectionKinds.includes(row.kind as PageSectionKind)
    )
      sectionRows.set(row.blockId, row);
    else if (
      row.family === "richText" &&
      richTextBlockKinds.includes(row.kind as RichTextBlockKind)
    )
      richRows.set(row.blockId, row);
    else fail("$.kind", "kind", "unknown Page storage row kind");
  }
  const localeSections = new Map<
    string,
    Map<string, Record<string, unknown>>
  >();
  localeSections.set(sourceLocale, new Map());
  const sectionNodes = new Map<string, Record<string, unknown>>();
  for (const row of [...sectionRows.values()].sort(compareStorageRows)) {
    const shared = pageStorageJSON(row.sharedData as PageSectionData);
    const protoCase = (row.sharedData as PageSectionData).value.case;
    if (
      pageSectionKindByProtoCase[
        protoCase as keyof typeof pageSectionKindByProtoCase
      ] !== row.kind
    )
      fail(
        "$.kind",
        "kind_mismatch",
        "row payload kind does not match storage kind",
      );
    if (!row.locales.some((locale) => locale.locale === sourceLocale))
      fail(
        "$.sourceLocale",
        "source_overlay",
        "each Page section requires source locale data",
      );
    const placement: Record<string, unknown> = { index: row.position };
    if (row.parentBlockId !== undefined) {
      placement.parentSectionId = row.parentBlockId;
      if (!row.containerSlot.startsWith("column-"))
        fail(
          "$.containerSlot",
          "slot",
          "nested Page section must name a column",
        );
      placement.columnId = row.containerSlot.slice("column-".length);
    } else if (row.containerSlot !== "sections")
      fail(
        "$.containerSlot",
        "slot",
        "root Page section must use sections slot",
      );
    const node = { section: { id: row.blockId, ...shared }, placement };
    sectionNodes.set(row.blockId, node);
    for (const locale of row.locales) {
      const values =
        localeSections.get(locale.locale) ??
        new Map<string, Record<string, unknown>>();
      values.set(row.blockId, {
        sectionId: row.blockId,
        ...pageStorageJSON(locale.data as PageSectionLocaleData),
      });
      localeSections.set(locale.locale, values);
    }
  }
  const consumedRich = new Set<string>();
  for (const [sectionID, sectionRow] of sectionRows) {
    if (sectionRow.kind !== "rich-text") continue;
    const descendants: ContentBlockStorageRow[] = [];
    for (const candidate of richRows.values()) {
      let parent = candidate.parentBlockId;
      const ancestry = new Set<string>();
      while (parent !== undefined) {
        if (parent === sectionID) {
          descendants.push({
            ...candidate,
            parentBlockId:
              candidate.parentBlockId === sectionID
                ? undefined
                : candidate.parentBlockId,
          });
          consumedRich.add(candidate.blockId);
          break;
        }
        if (ancestry.has(parent))
          fail("$.parentBlockId", "cycle", "rich-text storage parent cycle");
        ancestry.add(parent);
        parent = richRows.get(parent)?.parentBlockId;
      }
    }
    const rich = materializeRichTextDocumentStorage(
      RichTextProfile.PAGE,
      sourceLocale,
      descendants,
    );
    const richJSON = mutableRecord(toJson(RichTextDocumentSchema, rich));
    const node = required(
      sectionNodes.get(sectionID),
      "$.section",
      "rich-text section row is required",
    );
    const section = mutableRecord(node.section);
    const sharedRich = mutableRecord(section.richText);
    sharedRich.blocks = richJSON.base;
    section.richText = sharedRich;
    for (const rawOverlay of (richJSON.localeOverlays ?? []) as unknown[]) {
      const richOverlay = mutableRecord(rawOverlay);
      const locale = String(richOverlay.locale);
      const values =
        localeSections.get(locale) ??
        new Map<string, Record<string, unknown>>();
      const localized = values.get(sectionID) ?? {
        sectionId: sectionID,
        richText: {},
      };
      const localizedRich = mutableRecord(localized.richText);
      localizedRich.blocks = richOverlay;
      localized.richText = localizedRich;
      values.set(sectionID, localized);
      localeSections.set(locale, values);
    }
  }
  if (consumedRich.size !== richRows.size)
    fail(
      "$.parentBlockId",
      "orphan",
      "rich-text Block is not owned by a Page rich-text section",
    );
  const raw = {
    blockCatalogFingerprint: contentBlockCatalogFingerprint,
    sourceLocale,
    base: { nodes: [...sectionNodes.values()] },
    localeOverlays: [...localeSections]
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([locale, sections]) => ({
        locale,
        sections: [...sections.values()].sort((left, right) =>
          String(left.sectionId).localeCompare(String(right.sectionId)),
        ),
      })),
  } as JsonValue;
  return normalizePageDocument(
    fromJson(PageDocumentSchema, raw),
    ContentValidationMode.RESTORE_SNAPSHOT,
  );
}
export function materializeLocalizedPageDocumentStorage(
  locale: string,
  rows: readonly ContentBlockStorageRow[],
): LocalizedPageDocument {
  return materializeLocalizedPageDocument(
    materializePageDocumentStorage(locale, rows),
    locale,
  );
}

function activeReference(
  attachment: FileAttachment | undefined,
  blockId: string,
  referencePath: string,
): ContentBlockMediaReference | undefined {
  return attachment?.state.case === "activeFileId"
    ? {
        $typeName: "api.content.v1.ContentBlockMediaReference",
        blockId,
        referencePath,
        activeFileId: attachment.state.value,
      }
    : undefined;
}
export function extractRichTextFileReferences(
  document: RichTextDocument,
): ContentBlockMediaReference[] {
  validateRichTextDocument(document, ContentValidationMode.RESTORE_SNAPSHOT);
  const result: ContentBlockMediaReference[] = [];
  for (const node of document.base!.nodes) {
    const block = node.block!;
    if (block.value.case === "file") {
      const ref = activeReference(
        block.value.value.props?.attachment,
        block.id,
        "file",
      );
      if (ref) result.push(ref);
    }
    if (block.value.case === "shader")
      block.value.value.props?.stages.forEach((stage, stageIndex) =>
        stage.channels.forEach((channel, channelIndex) => {
          const one = activeReference(
            channel.file,
            block.id,
            `shader.stages.${stageIndex}.channels.${channelIndex}.file`,
          );
          if (one) result.push(one);
          channel.faces.forEach((face, faceIndex) => {
            const ref = activeReference(
              face,
              block.id,
              `shader.stages.${stageIndex}.channels.${channelIndex}.faces.${faceIndex}`,
            );
            if (ref) result.push(ref);
          });
        }),
      );
  }
  return result;
}
export function extractPageFileReferences(
  document: PageDocument,
): ContentBlockMediaReference[] {
  validatePageDocument(document, ContentValidationMode.RESTORE_SNAPSHOT);
  const result: ContentBlockMediaReference[] = [];
  for (const node of document.base!.nodes) {
    const section = node.section!;
    if (section.value.case === "richText" && section.value.value.blocks) {
      const rich: RichTextDocument = {
        $typeName: "api.content.v1.RichTextDocument",
        blockCatalogFingerprint: contentBlockCatalogFingerprint,
        profile: RichTextProfile.PAGE,
        sourceLocale: document.sourceLocale,
        base: section.value.value.blocks,
        localeOverlays: document.localeOverlays.flatMap((overlay) => {
          const localized = overlay.sections.find(
            (item) => item.sectionId === section.id,
          );
          return localized?.value.case === "richText" &&
            localized.value.value.blocks
            ? [localized.value.value.blocks]
            : [];
        }),
      };
      result.push(...extractRichTextFileReferences(rich));
    }
    if (section.value.case === "immersiveScene")
      section.value.value.units.forEach((unit) => {
        const props = unit.props;
        for (const [field, path] of [
          ["meshFile", "immersive.mesh"],
          ["meshOptimizationSourceFile", "immersive.optimization_source"],
          ["meshOptimizationFile", "immersive.optimized_mesh"],
          ["textureFile", "immersive.texture"],
          ["darkTextureFile", "immersive.dark_texture"],
        ] as const) {
          const ref = activeReference(
            props?.[field],
            section.id,
            path + "." + unit.id,
          );
          if (ref) result.push(ref);
        }
      });
  }
  return result;
}

function canonicalStorageData(
  row: ContentBlockStorageRow,
  data:
    | RichTextBlockData
    | PageSectionData
    | RichTextBlockLocaleData
    | PageSectionLocaleData,
): Record<string, unknown> {
  const value =
    row.family === "richText"
      ? data.$typeName.endsWith("LocaleData")
        ? toJson(RichTextBlockLocaleDataSchema, data as RichTextBlockLocaleData)
        : toJson(RichTextBlockDataSchema, data as RichTextBlockData)
      : data.$typeName.endsWith("LocaleData")
        ? toJson(PageSectionLocaleDataSchema, data as PageSectionLocaleData)
        : toJson(PageSectionDataSchema, data as PageSectionData);
  return Object.fromEntries(
    Object.entries(mutableRecord(value)).sort(([left], [right]) =>
      left.localeCompare(right),
    ),
  );
}
export function canonicalStorageDocumentBytes(
  profile: string,
  rows: readonly ContentBlockStorageRow[],
): Uint8Array {
  const blocks = [...rows]
    .sort((left, right) => left.blockId.localeCompare(right.blockId))
    .map((row) => ({
      id: row.blockId,
      parent_id: row.parentBlockId ?? null,
      container_slot: row.containerSlot,
      position: row.position,
      kind: row.kind,
      shared_data: canonicalStorageData(row, row.sharedData),
      locales: [...row.locales]
        .sort((left, right) => left.locale.localeCompare(right.locale))
        .map((locale) => ({
          locale: locale.locale,
          data: canonicalStorageData(row, locale.data),
        })),
    }));
  return new TextEncoder().encode(JSON.stringify({ profile, blocks }));
}
async function sha256Hex(value: Uint8Array): Promise<string> {
  const digest = await globalThis.crypto.subtle.digest(
    "SHA-256",
    value as BufferSource,
  );
  return [...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}
export function canonicalRichTextDocumentBytes(
  document: RichTextDocument,
): Uint8Array {
  return canonicalStorageDocumentBytes(
    profileName(document.profile),
    flattenRichTextDocumentStorage(
      document,
      ContentValidationMode.RESTORE_SNAPSHOT,
    ),
  );
}
export function canonicalPageDocumentBytes(document: PageDocument): Uint8Array {
  return canonicalStorageDocumentBytes(
    "page",
    flattenPageDocumentStorage(
      document,
      ContentValidationMode.RESTORE_SNAPSHOT,
    ),
  );
}
export function canonicalRichTextDocumentHash(
  document: RichTextDocument,
): Promise<string> {
  return sha256Hex(canonicalRichTextDocumentBytes(document));
}
export function canonicalPageDocumentHash(
  document: PageDocument,
): Promise<string> {
  return sha256Hex(canonicalPageDocumentBytes(document));
}
export function canonicalLocalizedRichTextDocumentBytes(
  document: LocalizedRichTextDocument,
): Uint8Array {
  validateLocalizedRichTextDocument(document);
  return toBinary(LocalizedRichTextDocumentSchema, document);
}
export function canonicalLocalizedPageDocumentBytes(
  document: LocalizedPageDocument,
): Uint8Array {
  validateLocalizedPageDocument(document);
  return toBinary(LocalizedPageDocumentSchema, document);
}

export function richTextMutationTouchesSource(
  batch: RichTextBlockMutationBatch,
  sourceLocale: string,
): boolean {
  return (
    batch.baseMutations.some(
      (mutation) =>
        mutation.operation.case === "delete" ||
        mutation.operation.case === "move" ||
        (mutation.operation.case === "upsert" &&
          mutation.operation.value.node?.placement !== undefined),
    ) ||
    batch.localeMutationGroups.some(
      (group) => group.locale === sourceLocale && group.mutations.length > 0,
    )
  );
}
export function pageMutationTouchesSource(
  batch: PageSectionMutationBatch,
  sourceLocale: string,
): boolean {
  return (
    batch.baseMutations.some(
      (mutation) =>
        mutation.operation.case === "delete" ||
        mutation.operation.case === "move" ||
        (mutation.operation.case === "upsert" &&
          mutation.operation.value.node?.placement !== undefined),
    ) ||
    batch.localeMutationGroups.some(
      (group) => group.locale === sourceLocale && group.mutations.length > 0,
    )
  );
}
